import{_ as a}from"./chunks/reservations.BPLsWE3r.js";import{_ as r,o as t,c as o,a2 as s}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Αναζήτηση και έλεγχος κρατήσεων","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/reservations.md","filePath":"el/plus/reservations.md"}'),n={name:"el/plus/reservations.md"};function l(i,e,p,c,h,d){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="αναζητηση-και-ελεγχος-κρατησεων" tabindex="-1">Αναζήτηση και έλεγχος κρατήσεων <a class="header-anchor" href="#αναζητηση-και-ελεγχος-κρατησεων" aria-label="Permalink to &quot;Αναζήτηση και έλεγχος κρατήσεων&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Πηγαίος κώδικας TransferBook+ v0.7.9. Το παρόν είναι τοπικό προσχέδιο προς έλεγχο, όχι επιβεβαίωση διαθεσιμότητας στην παραγωγή. Ελέγξτε την εγκατεστημένη έκδοση και τα δικαιώματά σας.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/reservations.png"><img src="'+a+'" alt="Κρατήσεις (Master Reservations): αναζήτηση, φίλτρα κατάστασης, δρομολόγια, αναθέσεις και συνολικές χρεώσεις."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Κρατήσεις (Master Reservations): αναζήτηση, φίλτρα κατάστασης, δρομολόγια, αναθέσεις και συνολικές χρεώσεις.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή. Έχουν καλυφθεί αναγνωριστικά στοιχεία.</p><h2 id="σκοπος-και-προσβαση" tabindex="-1">Σκοπός και πρόσβαση <a class="header-anchor" href="#σκοπος-και-προσβαση" aria-label="Permalink to &quot;Σκοπός και πρόσβαση&quot;">​</a></h2><p>Χρησιμοποιήστε τη διαχείριση κρατήσεων με εξουσιοδοτημένη πρόσβαση στα στοιχεία της εταιρείας.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Αναζητήστε με κωδικό κράτησης, όνομα, αριθμό πτήσης ή ξενοδοχείο.</li><li>Επιλέξτε φίλτρο <strong>All</strong>, <strong>New</strong>, <strong>Confirmed</strong>, <strong>Assigned</strong>, <strong>In Transit</strong>, <strong>Completed</strong> ή <strong>Cancelled</strong>.</li><li>Επιλέξτε τη σωστή γραμμή και ελέγξτε επιβάτες, διαδρομή, ώρα παραλαβής, όχημα/οδηγό και συνολική τιμή.</li><li>Εφόσον έχετε δικαίωμα, χρησιμοποιήστε τα διαθέσιμα εργαλεία επεξεργασίας επιλέξιμης κράτησης. Ελέγξτε τα νέα στοιχεία και την τιμή πριν από την αποθήκευση.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Οι λεπτομέρειες αντιστοιχούν στον επιλεγμένο κωδικό. Οι τελικές καταστάσεις προστατεύονται από συνήθη επεξεργασία.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Αν δεν εμφανίζεται κράτηση, αφαιρέστε το φίλτρο κατάστασης και ελέγξτε τον κωδικό και την εταιρεία. Αν μια ενέργεια δεν διατίθεται, ελέγξτε ρόλο και κατάσταση. Δείτε τον <a href="/el/plus/reservation-lifecycle.html">κύκλο ζωής</a>.</p>',15)])])}const f=r(n,[["render",l]]);export{u as __pageData,f as default};
